describe('Payment Processing Loading State', () => {
  beforeEach(() => {
    cy.visit('/payment');
  });

  it('should display loading state while payment is processing', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payment/process').as('processPayment');

    // Click the pay button
    cy.get('[data-testid="pay-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Processing payment');

    // Verify pay button is disabled during processing
    cy.get('[data-testid="pay-button"]').should('be.disabled');

    // Wait for the API call to complete
    cy.wait('@processPayment');

    // Verify loading indicator disappears after successful payment
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="loading-text"]').should('not.exist');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Payment successful');

    // Verify user is redirected to confirmation page
    cy.url().should('include', '/payment/success');
  });

  it('should handle payment processing timeout and display error state', () => {
    // Intercept the payment API call and delay the response
    cy.intercept('POST', '/api/payment/process', (req) => {
      req.reply((res) => {
        res.delay(10000); // Simulate timeout
        res.send({ statusCode: 200, body: { success: true } });
      });
    }).as('processPaymentTimeout');

    // Click the pay button
    cy.get('[data-testid="pay-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Wait for the timeout to occur
    cy.wait('@processPaymentTimeout', { timeout: 15000 });

    // Verify error state is displayed after timeout
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Payment timed out');

    // Verify loading indicator is removed
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify pay button is re-enabled
    cy.get('[data-testid="pay-button"]').should('not.be.disabled');

    // Verify user is still on payment page
    cy.url().should('include', '/payment');
  });
});
